export class FushiWriting {
    private static readonly IMAGEFOLDER = 'assets/images/jamos/'

    syllableToImageTag(syllable: string): string {
        let sy = JAMOS.find((x) => x.sy === syllable);

        if (sy) {
            return '<img width="48px" src="' + FushiWriting.IMAGEFOLDER + sy.file + '"/>';
        }

        return syllable;
    }

    syllablesToImageTags(syllables: string[] = [], glue: string = ''): string {
        let images: string[] = [];

        if (0 === syllables.length) {
            return '';
        }

        for (let s = 0; s < syllables.length; s++) {
            images.push(this.syllableToImageTag(syllables[s]));
        }

        return images.join(glue);
    }
}

interface FushiWritingSyllable {
    sy: string;
    file: string;
}

